90	        </Link>
91	      </div>
92	
93	      <Card as="section" className="flex flex-col gap-3">
94	        <h2 className="text-h3">{t("listener.topicsHeading")}</h2>
95	        <ul className="flex flex-wrap gap-2">
96	          {provider.topics.map((topic) => (
97	            <li key={topic}>
98	              <Tag>{topic}</Tag>
99	            </li>
100	          ))}
101	        </ul>
102	        <h2 className="mt-2 text-h3">{t("listener.languagesHeading")}</h2>
103	        <p className="text-base text-ink">{provider.languages.join(", ")}</p>
104	      </Card>
105	
106	      <Card as="section" className="flex flex-col gap-3">
107	        <h2 className="text-h3">{t("listener.pricingHeading")}</h2>
108	        <p className="text-base text-ink">
109	          {formatBlockPrice(provider.price_block_15_cents, 15)} ·{" "}
110	          {formatBlockPrice(provider.price_block_30_cents, 30)} ·{" "}
111	          {formatBlockPrice(provider.price_block_45_cents, 45)}
112	        </p>
113	      </Card>
114	
115	      <section className="flex flex-col gap-3">
116	        <h2 className="text-h2">{t("listener.reviewsHeading")}</h2>
117	        {reviews.length === 0 ? (
118	          <Card>
119	            <p className="text-base text-ink-soft">{t("listener.noReviews")}</p>
120	          </Card>
121	        ) : (
122	          <ul className="flex flex-col gap-3">
123	            {reviews.map((review) => (
124	              <Card as="li" key={review.id} className="flex flex-col gap-1.5">
125	                <p className="text-base text-ink">{review.comment}</p>
126	                <p className="text-sm font-bold text-ink-soft">
127	                  ★ {review.rating}
128	                </p>
129	              </Card>
130	            ))}
131	          </ul>
132	        )}
133	      </section>
134	    </div>
135	  );
136	}
