31	    getBooking(id),
32	    getSessionByBooking(id),
33	  ]);
34	  if (!booking || !session) notFound();
35	  const [provider, review] = await Promise.all([
36	    getApprovedProvider(booking.provider_id),
37	    getReviewForSession(session.id),
38	  ]);
39	
40	  const name = provider?.display_name ?? "your listener";
41	
42	  return (
43	    <div className="mx-auto flex w-full max-w-xl flex-col gap-6">
