53	            </p>
54	          </div>
55	        </Card>
56	      ) : (
57	        <Card as="section">
58	          <RatingTipForm sessionId={session.id} providerId={booking.provider_id} />
59	        </Card>
60	      )}
61	
62	      <Card as="section" className="flex flex-col gap-3">
63	        <h2 className="text-h3">{t("summary.receiptHeading")}</h2>
64	        <dl className="flex flex-col gap-2 text-base">
