77	          {session.overage_minutes > 0 ? (
78	            <div className="flex items-center justify-between">
79	              <dt className="text-ink-soft">{t("summary.overageLabel")}</dt>
80	              <dd className="font-bold text-ink">
81	                {t("summary.minutesValue", { minutes: session.overage_minutes })}
82	              </dd>
83	            </div>
84	          ) : null}
85	          <div className="flex items-center justify-between border-t border-border pt-2 text-lg">
86	            <dt className="font-bold text-ink">{t("summary.totalLabel")}</dt>
87	            <dd className="font-bold text-ink">
88	              {formatCents(session.total_price_cents)}
89	            </dd>
90	          </div>
91	        </dl>
92	      </Card>
93	
94	      <div className="flex flex-wrap gap-3">
95	        <Link href={`/book/${booking.provider_id}`} className="rounded-btn">
