3	import * as React from "react";
4	import { useRouter } from "next/navigation";
5	import { Phone, Mic } from "lucide-react";
6	import { Card } from "@/components/ui/Card";
7	import { Button } from "@/components/ui/Button";
8	import { Avatar } from "@/components/ui/Avatar";
9	import { CallStage } from "@/components/session/CallStage";
10	import { startSession, endSession } from "@/app/(customer)/session/actions";
11	import { t } from "@/lib/i18n";
12	
13	export function SessionFlow({
14	  bookingId,
15	  name,
16	  avatarColor,
17	}: {
18	  bookingId: string;
19	  name: string;
20	  avatarColor: string;
21	}) {
22	  const router = useRouter();
23	  const [phase, setPhase] = React.useState<"precall" | "incall">("precall");
24	  const [joining, setJoining] = React.useState(false);
25	  const [error, setError] = React.useState<string | null>(null);
26	
27	  async function join() {
28	    setJoining(true);
29	    setError(null);
30	    const res = await startSession(bookingId);
31	    if (res.error) {
32	      setError(res.error);
33	      setJoining(false);
34	      return;
35	    }
36	    setPhase("incall");
37	  }
38	
39	  if (phase === "incall") {
40	    return (
41	      <CallStage
42	        name={name}
43	        avatarColor={avatarColor}
44	        endLabel={t("session.end")}
45	        onEnd={async (elapsed) => {
46	          await endSession(bookingId, elapsed);
47	          router.push(`/session/${bookingId}/summary`);
48	        }}
49	      />
50	    );
51	  }
52	
53	  return (
54	    <Card className="mx-auto flex w-full max-w-xl flex-col items-center gap-6 p-8 text-center max-md:p-6">
55	      <Avatar name={name} color={avatarColor} size={96} />
56	      <span
57	        aria-hidden="true"
58	        className="flex items-center gap-2"
59	      >
60	        {[0, 1, 2].map((i) => (
61	          <span
62	            key={i}
63	            className="size-2.5 rounded-pill bg-primary"
64	            style={{
65	              animation: `wf 0.9s var(--ease-warm) ${i * 0.15}s infinite alternate`,
66	            }}
67	          />
68	        ))}
69	      </span>
70	      <div className="flex flex-col gap-2">
71	        <h1 className="text-h2">{t("session.connectingTitle", { name })}</h1>
72	        <p className="text-lg text-ink-soft">{t("session.connectingHelp")}</p>
73	      </div>
74	      <p className="flex items-center gap-2 text-base font-bold text-success">
75	        <Mic size={18} strokeWidth={2} aria-hidden="true" />
76	        {t("session.micCheck")}
77	      </p>
78	
79	      {error ? (
80	        <p role="alert" className="text-base font-semibold text-alert">
81	          {error}
82	        </p>
83	      ) : null}
84	
85	      <div className="flex w-full flex-col gap-3">
86	        <Button full icon={Phone} onClick={join} disabled={joining}>
87	          {joining ? t("ui.loading") : t("session.join")}
88	        </Button>
89	        <Button full variant="ghost" onClick={() => router.push("/account")}>
90	          {t("session.cancel")}
91	        </Button>
92	      </div>
93	    </Card>
94	  );
95	}
