1	"use client";
2	
3	import * as React from "react";
4	import { CircleAlert, CreditCard, ShieldCheck, Check } from "lucide-react";
5	import { Button } from "@/components/ui/Button";
6	import { Field, Input } from "@/components/ui/Field";
7	import { createBooking } from "@/app/(customer)/actions";
8	import { formatCents } from "@/lib/format";
9	import { t } from "@/lib/i18n";
10	import { type BlockMinutes } from "@/lib/pricing";
11	
12	export interface BookingProvider {
13	  id: string;
14	  displayName: string;
15	  prices: Record<BlockMinutes, number>;
16	  overagePerMinCents: number;
17	}
18	
19	const BLOCKS: BlockMinutes[] = [15, 30, 45];
20	
21	export function BookingForm({
22	  provider,
23	  defaultMode,
24	}: {
25	  provider: BookingProvider;
26	  defaultMode: "now" | "scheduled";
27	}) {
28	  const [block, setBlock] = React.useState<BlockMinutes>(30);
29	  const [mode, setMode] = React.useState<"now" | "scheduled">(defaultMode);
30	  const [scheduledAt, setScheduledAt] = React.useState("");
31	  const [submitting, setSubmitting] = React.useState(false);
32	  const [error, setError] = React.useState<string | null>(null);
33	  const [fieldErrors, setFieldErrors] = React.useState<Record<string, string>>({});
34	
35	  const priceCents = provider.prices[block];
36	
37	  async function onConfirm() {
38	    setSubmitting(true);
39	    setError(null);
40	    setFieldErrors({});
41	    const res = await createBooking({
42	      providerId: provider.id,
43	      blockMinutes: block,
44	      startMode: mode,
45	      scheduledAt:
46	        mode === "scheduled" && scheduledAt
47	          ? new Date(scheduledAt).toISOString()
48	          : undefined,
49	    });
50	    // Success redirects; only errors return.
51	    if (res?.error) {
52	      setError(res.error);
53	      setFieldErrors(res.fieldErrors ?? {});
54	      setSubmitting(false);
55	    }
56	  }
57	
58	  return (
59	    <div className="flex flex-col gap-6">
60	      {error ? (
61	        <p
62	          role="alert"
63	          className="flex items-start gap-2 rounded-card border-l-4 border-alert bg-alert-tint px-4 py-3 text-base"
64	        >
65	          <CircleAlert size={20} aria-hidden="true" className="mt-0.5 text-alert" />
66	          {error}
67	        </p>
68	      ) : null}
69	
70	      <fieldset className="flex flex-col gap-3">
71	        <legend className="text-h3">{t("booking.chooseLength")}</legend>
72	        <div className="grid grid-cols-3 gap-3 max-sm:grid-cols-1">
73	          {BLOCKS.map((minutes) => {
74	            const selected = block === minutes;
75	            return (
76	              <label
77	                key={minutes}
78	                className={[
79	                  "flex cursor-pointer flex-col gap-1 rounded-card border bg-surface p-4 has-[:focus-visible]:shadow-[0_0_0_3px_var(--color-focus)]",
80	                  selected
81	                    ? "border-2 border-primary bg-primary-tint"
82	                    : "border-border-strong hover:bg-primary-tint/40",
83	                ].join(" ")}
84	              >
85	                <input
86	                  type="radio"
87	                  name="block"
88	                  value={minutes}
89	                  checked={selected}
90	                  onChange={() => setBlock(minutes)}
91	                  className="sr-only"
92	                />
93	                <span className="flex items-center justify-between">
94	                  <span className="text-lg font-bold text-ink">
95	                    {t("booking.minutes", { minutes })}
96	                  </span>
97	                  {selected ? (
98	                    <Check size={18} strokeWidth={2.5} aria-hidden="true" className="text-primary" />
99	                  ) : null}
100	                </span>
101	                <span className="text-base font-bold text-ink-soft">
102	                  {formatCents(provider.prices[minutes])}
103	                </span>
104	              </label>
105	            );
106	          })}
107	        </div>
108	      </fieldset>
109	
110	      <fieldset className="flex flex-col gap-3">
111	        <legend className="text-h3">{t("booking.startHeading")}</legend>
112	        <div className="flex flex-col gap-2">
113	          {(["now", "scheduled"] as const).map((value) => (
114	            <label
115	              key={value}
116	              className="flex items-center gap-3 rounded-card border border-border-strong bg-surface px-4 py-3 text-base font-bold text-ink has-[:focus-visible]:shadow-[0_0_0_3px_var(--color-focus)]"
117	            >
118	              <input
119	                type="radio"
120	                name="mode"
121	                value={value}
122	                checked={mode === value}
123	                onChange={() => setMode(value)}
124	                className="size-5"
