88	
89	      {captionsOn ? (
90	        <p
91	          aria-live="polite"
92	          className="w-full rounded-card border border-border bg-bg p-4 text-base text-ink"
93	        >
94	          {t("session.captionsSample")}
95	        </p>
96	      ) : null}
97	
98	      <div className="flex w-full flex-wrap items-center justify-center gap-3 border-t border-border pt-6">
99	        <button
100	          type="button"
101	          onClick={() => setMuted((m) => !m)}
102	          aria-pressed={muted}
103	          className="inline-flex min-h-12 items-center gap-2 rounded-btn border border-border-strong bg-surface px-5 text-base font-bold text-ink hover:bg-surface-sunk aria-pressed:bg-surface-sunk"
104	        >
105	          {muted ? (
106	            <MicOff size={20} strokeWidth={2} aria-hidden="true" />
107	          ) : (
108	            <Mic size={20} strokeWidth={2} aria-hidden="true" />
109	          )}
110	          {muted ? t("session.unmute") : t("session.mute")}
111	        </button>
112	
113	        <button
114	          type="button"
115	          onClick={() => setCaptionsOn((c) => !c)}
116	          aria-pressed={captionsOn}
117	          className="inline-flex min-h-12 items-center gap-2 rounded-btn border border-border-strong bg-surface px-5 text-base font-bold text-ink hover:bg-surface-sunk aria-pressed:bg-primary-tint aria-pressed:text-primary-dark"
118	        >
119	          <Captions size={20} strokeWidth={2} aria-hidden="true" />
120	          {captionsOn ? t("session.captionsOn") : t("session.captionsOff")}
121	        </button>
122	
123	        <button
124	          type="button"
125	          onClick={end}
126	          disabled={ending}
127	          className="inline-flex min-h-12 items-center gap-2 rounded-btn bg-alert px-6 text-base font-bold text-surface hover:brightness-95 disabled:opacity-60"
128	        >
129	          <PhoneOff size={20} strokeWidth={2} aria-hidden="true" />
130	          {ending ? t("session.ending") : endLabel}
131	        </button>
132	      </div>
133	    </div>
134	  );
135	}
